"""Migration of legacy OPP_MASTER validation rules in source-file order."""

from decimal import Decimal, InvalidOperation
from typing import Any


def _value(record: dict, field: str) -> Any:
    """Return a field value, treating missing and None values as legacy empty."""
    value = record.get(field, "")
    return "" if value is None else value


def _text(record: dict, field: str) -> str:
    return str(_value(record, field))


def _number(value: Any) -> Decimal:
    """Apply legacy numeric coercion: empty values compare as zero."""
    if value is None or value == "":
        return Decimal("0")
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        # Inputs are specified as numbers or numeric strings. This fallback
        # preserves empty-like behavior without introducing a new validation.
        return Decimal("0")


def _date_gte(left: Any, right: Any) -> bool:
    """Legacy date >= comparison, including the 00000000 no-value sentinel."""
    left_text = "" if left is None else str(left)
    right_text = "" if right is None else str(right)
    if left_text == "00000000" or right_text == "00000000":
        return False
    return left_text >= right_text


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Validate an OPP_MASTER post-write image using legacy VRL semantics."""
    errors: list[dict] = []
    old_record = old if event == "UPDATE" and old is not None else {}

    def fail(code: str, message: str, severity: str = "BLOCK") -> None:
        errors.append({"code": code, "message": message, "severity": severity})

    stat_cd = _text(record, "STAT_CD")
    amount = _number(_value(record, "AMT"))
    lost_rsn = _text(record, "LOST_RSN")
    close_dt = _text(record, "CLOSE_DT")
    stage_pct = _number(_value(record, "STAGE_PCT"))

    # OPP-001
    if event in ("INSERT", "UPDATE") and not amount >= Decimal("0"):
        fail("E3001", "Amount negative")

    # OPP-002
    if event in ("INSERT", "UPDATE") and stat_cd == "W" and amount == Decimal("0"):
        fail("E3002", "Won opportunity requires amount")

    # OPP-003
    if event in ("INSERT", "UPDATE") and stat_cd == "L" and lost_rsn == "":
        fail("E3003", "Lost reason required")

    # OPP-004
    if event in ("INSERT", "UPDATE") and stat_cd == "W" and close_dt == "00000000":
        fail("E3004", "Won opportunity requires close date")

    # OPP-005
    if (
        event == "UPDATE"
        and _text(old_record, "STAT_CD") == "W"
        and stat_cd != "W"
    ):
        fail("E3005", "Cannot reopen a won opportunity")

    # OPP-006
    if event in ("INSERT", "UPDATE"):
        valid_stage = (
            (stat_cd == "P" and stage_pct == Decimal("10"))
            or (stat_cd == "Q" and stage_pct == Decimal("25"))
            or (stat_cd == "N" and stage_pct == Decimal("60"))
            or (stat_cd == "W" and stage_pct == Decimal("100"))
            or (stat_cd == "L" and stage_pct == Decimal("0"))
        )
        if not valid_stage:
            fail("E3006", "Stage percent inconsistent with status")

    # OPP-007
    if event == "INSERT" and not (
        close_dt == "00000000" or _date_gte(close_dt, today)
    ):
        fail("E3007", "Close date in past", "WARN")

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether legacy write processing must reject the write."""
    return any(error.get("severity") == "BLOCK" for error in errors)
